#!/usr/bin/env node
// SPDX-License-Identifier: AGPL-3.0-only
// Loombre :: scripts/docs/gen-lpp-spec.mjs
//
// LPP v1, Lane W6 (developer kit) — surfaces the FROZEN LPP v1 protocol
// spec inside the docs site without hand-copying it. The canonical spec
// lives at packages/plugin-protocol/spec/lpp-v1.md: it is itself a
// generated file (`pnpm --filter @loombre/plugin-protocol run generate`,
// produced from that package's src/, drift-checked there by
// test/spec-doc-drift.spec.ts). This script copies that file byte-for-byte
// into docs/developer-guide/plugins/spec.md, with a short banner explaining
// where it came from — the SAME "generated, committed, drift-checked"
// pattern gen-settings-reference.mjs and gen-env-reference.mjs already
// establish for this docs suite (see scripts/docs/build.mjs's header for
// the precedent, followed exactly): the output below IS committed to the
// repo like any other doc page, and scripts/docs/build.mjs's drift check
// (`git diff --exit-code`) fails the build if regenerating this file
// produces different content than what's committed — i.e. the docs copy
// can never silently diverge from the frozen contract a real conformance
// run actually validates plugins against.
//
// Runs via plain `node` (unlike gen-settings-reference.mjs/gen-env-
// reference.mjs, which need `tsx` to import TypeScript source directly) —
// the source here is already committed Markdown, so no import/build step
// is involved at all.

import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = join(__dirname, "..", "..");
const SOURCE_PATH = join(REPO_ROOT, "packages", "plugin-protocol", "spec", "lpp-v1.md");
const OUTPUT_PATH = join(REPO_ROOT, "docs", "developer-guide", "plugins", "spec.md");

if (!existsSync(SOURCE_PATH)) {
  console.error(`gen-lpp-spec: FAIL — source spec not found at ${SOURCE_PATH} (packages/plugin-protocol not built/generated?)`);
  process.exit(1);
}

const source = readFileSync(SOURCE_PATH, "utf8");

const banner = [
  "<!-- GENERATED by scripts/docs/gen-lpp-spec.mjs — a byte-for-byte copy of",
  "     packages/plugin-protocol/spec/lpp-v1.md (itself generated from that",
  "     package's src/ by `pnpm --filter @loombre/plugin-protocol run",
  "     generate`, and drift-checked there by test/spec-doc-drift.spec.ts).",
  "     Do not edit by hand — edits are overwritten on the next",
  "     `pnpm docs:build`, and a divergence from the source fails the docs",
  "     build (scripts/docs/build.mjs's own drift check). -->",
  "",
  "> This is the FROZEN LPP v1 contract, copied byte-for-byte from",
  "> `packages/plugin-protocol/spec/lpp-v1.md` in the repository — the exact",
  "> document the conformance suite (see",
  "> [Conformance testing](./conformance.md)) validates plugins against, so it",
  "> can never read differently here than it does there. Start at the",
  "> [plugin developer kit overview](./index.md) if you haven't yet.",
  "",
  "",
].join("\n");

mkdirSync(dirname(OUTPUT_PATH), { recursive: true });
writeFileSync(OUTPUT_PATH, banner + source);

console.log(`gen-lpp-spec: copied packages/plugin-protocol/spec/lpp-v1.md (${source.length} bytes) -> docs/developer-guide/plugins/spec.md`);
